// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring for cascading push animation

const { fontFamily: oswaldFamily } = loadOswald();



export type ComponentNameProps = Record<string, any>;

const UserIcon: React.FC<{ size: number }> = ({ size }) => {
  return (
    <svg width={size * 0.65} height={size * 0.65} viewBox="0 0 100 100" fill="white" style={{ transform: 'translateY(10%)', transition: "none" }}>
      <circle cx="50" cy="35" r="22" style={{ transition: "none" }} />
      <path d="M 15 95 Q 15 65 50 65 Q 85 65 85 95 Z" style={{ transition: "none" }} />
    </svg>
  );
};

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 6,
  bookColor = "#ece7d8",
  iconColor = "#f27242",
  title = "APPOINTMENTS",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; 

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Map the 5 rows of the pyramid (from bottom to top)
  const rowsInfo = useMemo(() => [
    { count: 7, rowIdx: 4 }, // bottom row
    { count: 6, rowIdx: 3 },
    { count: 5, rowIdx: 2 },
    { count: 4, rowIdx: 1 },
    { count: 3, rowIdx: 0 }  // top row
  ], []);

  // Flatten rows into a precise sequential icon array mapping
  const iconList = useMemo(() => {
    const list: { row: number; col: number; count: number }[] = [];
    rowsInfo.forEach(r => {
      for (let c = 0; c < r.count; c++) {
        list.push({ row: r.rowIdx, col: c, count: r.count });
      }
    });
    return list;
  }, [rowsInfo]);

  // The book flies in smoothly with higher damping to prevent a hard bounce
  const bookEnterProgress = spring({
    frame: frame - 5,
    fps,
    config: { damping: 26, stiffness: 80 }
  });

  const bookWidth = 480 * s;
  const bookHeight = 680 * s;

  // The initial Y placement where the book lands before any icon pops up
  const baseBookY = interpolate(bookEnterProgress, [0, 1], [height + bookHeight, 1035 * s]);

  // Interpolate rotation to make the book float in at a dynamic angle and settle slightly tilted
  const bookRotation = interpolate(bookEnterProgress, [0, 1], [-18, -6]);

  // Compute staggered appearance for all 25 icons and accumulate the total "push" force
  let totalPushes = 0;
  const iconProgresses = iconList.map((_, i) => {
    const sVal = spring({
      frame: frame - (30 + i * 3),
      fps,
      config: { damping: 12, stiffness: 150 }
    });
    totalPushes += sVal;
    return sVal;
  });

  // As each icon scales in, it pushes the floating book upward dynamically
  const pushAmountPerIcon = 15 * s;
  const currentBookY = baseBookY - totalPushes * pushAmountPerIcon;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: oswaldFamily }}>
      
      {/* Book Element */}
      <div style={{
        position: 'absolute',
        left: width / 2 - bookWidth / 2,
        top: currentBookY - bookHeight / 2,
        width: bookWidth,
        height: bookHeight,
        backgroundColor: bookColor,
        borderRadius: `${4 * s}px ${16 * s}px ${16 * s}px ${4 * s}px`,
        boxShadow: `
          -${10 * s}px ${30 * s}px ${40 * s}px rgba(0,0,0,0.8),
          inset ${15 * s}px 0 ${20 * s}px rgba(0,0,0,0.08),
          inset -${2 * s}px 0 ${5 * s}px rgba(255,255,255,0.8)
        `,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        opacity: bookEnterProgress > 0 ? 1 : 0, // fully hidden before frame 5
        transform: `rotate(${bookRotation}deg)`,
        transition: 'none'
      }}>
        {/* Book Spine Crease Simulation */}
        <div style={{
          position: 'absolute',
          left: 20 * s,
          top: 0,
          bottom: 0,
          width: 12 * s,
          background: 'linear-gradient(to right, transparent, rgba(0,0,0,0.1) 40%, rgba(255,255,255,0.5) 70%, transparent)',
          transition: 'none'
        }} />
        
        {/* Book Title */}
        <div style={{
          fontFamily: oswaldFamily,
          fontSize: 66 * s,
          color: '#111',
          fontWeight: 600,
          transform: `scaleY(1.8)`,
          letterSpacing: -1 * s,
          paddingLeft: 20 * s,
          textAlign: 'center',
          width: '100%',
          lineHeight: 1,
          transition: 'none'
        }}>
          {title.toUpperCase()}
        </div>
      </div>

      {/* Pyramid Icons */}
      {iconList.map((icon, i) => {
        const sVal = iconProgresses[i];
        const iconRadius = 45 * s;
        
        // Compute precise grid positions based on canvas center and row counts
        const rowY = 1085 * s + icon.row * 120 * s;
        const rowWidth = icon.count * 90 * s + (icon.count - 1) * 30 * s;
        const startX = width / 2 - rowWidth / 2;
        
        const x = startX + icon.col * 120 * s + iconRadius;
        const y = rowY + iconRadius;

        return (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: x - iconRadius,
              top: y - iconRadius,
              width: iconRadius * 2,
              height: iconRadius * 2,
              backgroundColor: iconColor,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transform: `scale(${sVal})`,
              opacity: sVal > 0 ? 1 : 0, // hidden until its exact staggered entrance
              boxShadow: `0 ${10 * s}px ${20 * s}px rgba(0,0,0,0.5)`,
              transition: 'none'
            }}
          >
            <UserIcon size={iconRadius * 2} />
          </div>
        );
      })}

    </AbsoluteFill>
  );
};

export default ComponentName;